def link_copies(apps, schema_editor):
    """Existing client copies: point each item at the master item it most likely came from (same meal name,
    option name, then the same food, else the same place in the option)."""
    MealPlan = apps.get_model("nutrition", "MealPlan")
    MealItem = apps.get_model("nutrition", "MealItem")
    for copy in MealPlan.objects.filter(is_master=False, master__isnull=False):
        master = {}
        for it in MealItem.objects.filter(option__meal__plan_id=copy.master_id).select_related("option__meal"):
            master.setdefault((it.option.meal.name.lower(), it.option.name.lower()), []).append(it)
        for it in MealItem.objects.filter(option__meal__plan=copy).select_related("option__meal"):
            pool = master.get((it.option.meal.name.lower(), it.option.name.lower()), [])
            hit = next((m for m in pool if m.food_id == it.food_id), None)
            if hit is None:
                hit = next((m for m in pool if m.order == it.order), None)
            if hit is not None:
                it.origin_id = hit.id
                it.save(update_fields=["origin"])


